import heapq


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}          # name -> {"vip": bool}
        self._tickets = {}            # id -> ticket dict
        self._queue = []              # heap of (-vip, -priority_index, seq, ticket_id)
        self._seq = 0                 # monotonic open counter for FIFO tiebreak
        self._next_id = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        if name in self._customers:
            self._customers[name]["vip"] = self._customers[name]["vip"] or vip
        else:
            self._customers[name] = {"vip": vip}

    def open_ticket(
        self,
        customer: str,
        title: str,
        priority: str = "normal",
        description: str = "",
    ) -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty")
        if customer not in self._customers:
            raise ValueError(f"Unknown customer: {customer!r}")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority!r}")

        ticket_id = self._next_id
        self._next_id += 1
        vip = self._customers[customer]["vip"]
        priority_index = self.PRIORITIES.index(priority)

        self._tickets[ticket_id] = {
            "id": ticket_id,
            "customer": customer,
            "title": title,
            "priority": priority,
            "vip": vip,
            "status": "open",
            "description": description,
        }
        self._enqueue(ticket_id)
        return ticket_id

    def _enqueue(self, ticket_id: int) -> None:
        t = self._tickets[ticket_id]
        priority_index = self.PRIORITIES.index(t["priority"])
        # VIP first (0 before 1 -> use -int(vip)), then higher priority index first,
        # then FIFO order by sequence number.
        heapq.heappush(
            self._queue,
            (-int(t["vip"]), -priority_index, self._seq, ticket_id),
        )
        self._seq += 1

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, _, ticket_id = heapq.heappop(self._queue)
            t = self._tickets[ticket_id]
            # Skip tickets that are no longer open (e.g., stale heap entries).
            if t["status"] == "open":
                t["status"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        t = self._tickets.get(ticket_id)
        if t is None:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        if t["status"] == "closed":
            raise ValueError(f"Ticket {ticket_id} is already closed")
        t["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        t = self._tickets.get(ticket_id)
        if t is None:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        if t["status"] == "closed":
            raise ValueError(f"Cannot reopen closed ticket {ticket_id}")
        if t["status"] == "open":
            return
        t["status"] = "open"
        self._enqueue(ticket_id)

    def queue_length(self) -> int:
        return sum(
            1
            for _, _, _, ticket_id in self._queue
            if self._tickets[ticket_id]["status"] == "open"
        )

    def ticket(self, ticket_id: int) -> dict:
        t = self._tickets.get(ticket_id)
        if t is None:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        return dict(t)

    def tickets_of(self, customer: str) -> list[int]:
        return [
            ticket_id
            for ticket_id, t in self._tickets.items()
            if t["customer"] == customer
        ]
